/* a bank is its first lesson and the steps after it (x-hsk2, x-hsk2b … x-hsk2e): 8 phrases each, 40 in all */
function xSteps(L,u){var ids=[u];['b','c','d','e'].forEach(function(s){if(UNITS[L][u+s])ids.push(u+s);});return ids;}
XSTARTER.forEach(function(x){
  var L=x[0];if(!UNITS[L])return;
  EXAMS[L]=[{key:x[1],title:x[2],sub:x[3],ids:x[4].map(function(b){return b[2];})}];
  x[4].forEach(function(b,i){XBANK[b[0]]={L:L,name:b[1],tier:b[3]||i+1,ids:xSteps(L,b[2]),key:b[0]};XBANK[b[0]].ids.forEach(function(u){XBANK_OF[u]=b[0];});});
  XGOALS[L]=[{key:x[1],title:x[5].title,pre:x[5].pre,sub:x[5].sub,goals:x[5].goals}];
});
